              steps: ['config vpn ipsec phase1-interface', 'edit TO-B', 'set interface port1', 'set ike-version 2', 'set remote-gw 198.51.100.2', 'set proposal aes256-sha256', 'set dhgrp 14', 'set psksecret Lab-Psk-2026', 'end'],
