              hints: ['config router static → edit 3', '<code>set dst 10.64.0.0 255.255.0.0</code> → <code>set blackhole enable</code> → <code>set distance 254</code> → <code>end</code>'],
              steps: ['config router static', 'edit 3', 'set dst 10.64.0.0 255.255.0.0', 'set blackhole enable', 'set distance 254', 'end'],
