            id: 'fgt-66', vendor: 'fortigate', level: 5, title: 'VDOM yöneticisi ve vdom-link: kiracıya yetki ve internete çıkış yolu', minutes: 25, kind: 'firewall', hostname: 'FGT-A', pre: ['fgt-53'],
            up: ['port1', 'port2', 'port3'], hosts: ['203.0.113.1'],
